WITH base AS (SELECT id, customer_id, balance, opened_date, status, ROUND(balance, 2) balance_rounded FROM accounts WHERE opened_date > TO_DATE('2023-02-28') AND status NOT IN ('OPEN', 'FROZEN')) SELECT d.city, a.status, COUNT(*) AS rows_total, ROUND(SUM(a.balance_rounded), 2) AS total_balance_rounded, GROUPING_ID() AS level_id FROM base a JOIN customers d ON a.customer_id = d.id GROUP BY GROUPING SETS ((d.city, a.status), (d.city)) ORDER BY total_balance_rounded ASC;
